  run_id STRING COMMENT 'Run that wrote the row',
  updated_at TIMESTAMP COMMENT 'UTC time the row was written'
) USING DELTA
COMMENT 'One row per in-scope dataflow, in execution order';

CREATE TABLE IF NOT EXISTS {schema}.Assessment_RebindWorklist (
  dataflow_id STRING COMMENT 'Dataflow GUID being migrated',
  dataflow_name STRING COMMENT 'Dataflow name',
  workspace_id STRING COMMENT 'Dataflow workspace GUID',
  workspace_name STRING COMMENT 'Dataflow workspace name',
  wave INT COMMENT 'Wave of the dataflow',
  path STRING COMMENT 'Recommended path that creates the work: UpgradeWizard or SaveAs',
  consumer_type STRING COMMENT 'Dataflow / SemanticModel / Datamart / DataPipeline',
  consumer_id STRING COMMENT 'Consumer GUID',
  consumer_name STRING COMMENT 'Consumer name',
  consumer_workspace_id STRING COMMENT 'Consumer workspace GUID',
  consumer_workspace_name STRING COMMENT 'Consumer workspace name',
  uses_legacy_connector BOOLEAN COMMENT 'Consumer M text uses the legacy PowerBI.Dataflows connector',
  storage_mode STRING COMMENT 'Semantic model storage mode when known',
  action STRING COMMENT 'What to do',
  effort_days DOUBLE COMMENT 'Estimated effort',
  gen2_dataflow_id STRING COMMENT 'Id of the Gen2 copy when already created with Save-As',
  run_id STRING COMMENT 'Run that wrote the row',
  updated_at TIMESTAMP COMMENT 'UTC time the row was written'
) USING DELTA
COMMENT 'One row per dataflow and downstream item to re-point';

CREATE TABLE IF NOT EXISTS {schema}.Assessment_RunSummary (
  run_id STRING COMMENT 'Run id',
  started_at TIMESTAMP COMMENT 'Start',
  ended_at TIMESTAMP COMMENT 'End',
  status STRING COMMENT 'Succeeded / Partial / Failed',
  mode STRING COMMENT 'Run mode',
  workspaces_total INT COMMENT 'Workspaces known',
  workspaces_scanned INT COMMENT 'Workspaces scanned in this run',
  dataflows_total INT COMMENT 'Dataflows known',
  gen1_count INT COMMENT 'Gen1',
  gen2_count INT COMMENT 'Gen2',
  ready_count INT COMMENT 'Ready',
  needs_attention_count INT COMMENT 'Needs Attention',
  unsupported_count INT COMMENT 'Unsupported',
  deferred_count INT COMMENT 'Deferred',
  migrated_count INT COMMENT 'Migrated Gen1 -> Gen2 (type flips or Save-As results)',
  avg_complexity_score DOUBLE COMMENT 'Average complexity score of in-scope dataflows',
  total_effort_days DOUBLE COMMENT 'Total estimated effort',
  api_calls INT COMMENT 'API calls',
  api_throttled INT COMMENT 'HTTP 429 responses',
  error_count INT COMMENT 'Errors logged',
  notebook_version STRING COMMENT 'Notebook version'
) USING DELTA
COMMENT 'One row per run';

CREATE TABLE IF NOT EXISTS {schema}.Assessment_RunLog (
  run_id STRING COMMENT 'Run id',
  seq INT COMMENT 'Phase sequence number',
  phase STRING COMMENT 'Phase name',
  status STRING COMMENT 'Succeeded / Failed / Skipped / Partial',
  started_at TIMESTAMP COMMENT 'Start',
  ended_at TIMESTAMP COMMENT 'End',
  duration_sec DOUBLE COMMENT 'Duration',
  rows_in INT COMMENT 'Rows or entities processed',
  rows_out INT COMMENT 'Rows written',
  api_calls INT COMMENT 'API calls in the phase',
  api_retries INT COMMENT 'Retries in the phase',
  api_throttled INT COMMENT 'HTTP 429 responses in the phase',
  errors INT COMMENT 'Errors in the phase',
  message STRING COMMENT 'Summary or failure message',
  mode STRING COMMENT 'Run mode',
  params_json STRING COMMENT 'Effective parameters (no secrets)'
) USING DELTA
COMMENT 'One row per run phase';

CREATE TABLE IF NOT EXISTS {schema}.Assessment_ErrorLog (
  run_id STRING COMMENT 'Run id',
  ts TIMESTAMP COMMENT 'Error time',
  phase STRING COMMENT 'Phase',
  entity_type STRING COMMENT 'Workspace / Dataflow / Batch / ...',
  entity_id STRING COMMENT 'Entity id',
  endpoint STRING COMMENT 'Endpoint template',
  http_status INT COMMENT 'HTTP status',
  error_code STRING COMMENT 'API error code',
  message STRING COMMENT 'Message',
  attempt INT COMMENT 'Attempt number',
  retryable BOOLEAN COMMENT 'Retryable error',
  body_snippet STRING COMMENT 'Truncated response body'
) USING DELTA
COMMENT 'One row per error';

CREATE TABLE IF NOT EXISTS {schema}.Assessment_Checkpoint (
  entity_type STRING COMMENT 'Dataflow / Workspace / ScanBatch',
  entity_id STRING COMMENT 'Entity id',
  phase STRING COMMENT 'definition / refresh / datasources / upstream / pipelines / scan',
  status STRING COMMENT 'Done / Failed / Denied / NotFound',
  attempts INT COMMENT 'Attempts so far',
  last_attempt_at TIMESTAMP COMMENT 'Last attempt',
  completed_at TIMESTAMP COMMENT 'Last successful completion',
  source_version STRING COMMENT 'Entity version when collected (modification time or hash)',
  last_error STRING COMMENT 'Last error',
  run_id STRING COMMENT 'Run that wrote the row',
  updated_at TIMESTAMP COMMENT 'UTC time the row was written'
) USING DELTA
COMMENT 'One row per entity and phase';

CREATE TABLE IF NOT EXISTS {schema}.Assessment_RuleCatalog (
  rule_id STRING COMMENT 'Rule id',
  name STRING COMMENT 'Rule name',
  category STRING COMMENT 'Category',
  severity STRING COMMENT 'Blocker / Major / Minor / Info',
  impact_wizard STRING COMMENT 'Effect on the Upgrade Wizard path: Unsupported / NeedsAttention / Deferred / None',
  impact_saveas STRING COMMENT 'Effect on the Save-As path: Unsupported / NeedsAttention / Deferred / None',
  weight INT COMMENT 'Weight in the unsupported-features score',
  effort_days DOUBLE COMMENT 'Remediation effort',
  detection STRING COMMENT 'How the rule is detected',
  remediation STRING COMMENT 'Recommended action',
  confidence STRING COMMENT 'Verified (documented) / Heuristic',
  enabled BOOLEAN COMMENT 'Rule enabled',
  version STRING COMMENT 'Catalog version'
) USING DELTA
COMMENT 'One row per assessment rule';

CREATE TABLE IF NOT EXISTS {schema}.Assessment_GovernanceOverrides (
  scope STRING COMMENT 'Workspace or Dataflow',
  workspace_id STRING COMMENT 'Workspace GUID (required)',
  dataflow_id STRING COMMENT 'Dataflow GUID (empty for workspace scope)',
  business_owner STRING COMMENT 'Business owner',
  technical_owner STRING COMMENT 'Technical owner',
  support_team STRING COMMENT 'Support team',
  business_criticality STRING COMMENT 'High / Medium / Low',
  workspace_classification STRING COMMENT 'Classification',
  environment STRING COMMENT 'Dev / Test / Prod',
  defer BOOLEAN COMMENT 'Force the Deferred class',
  defer_reason STRING COMMENT 'Why migration is deferred',
  pin_wave INT COMMENT 'Pin the dataflow to a wave',
  wizard_status_actual STRING COMMENT 'Observed Upgrade Wizard status: Ready to migrate / Needs Attention / Upgrade unavailable',
  rollback_plan_defined BOOLEAN COMMENT 'Rollback strategy defined',
  uat_window_start DATE COMMENT 'Acceptance window start',
  uat_window_end DATE COMMENT 'Acceptance window end',
  notes STRING COMMENT 'Free text',
  updated_by STRING COMMENT 'Who maintained the row',
  updated_at TIMESTAMP COMMENT 'When'
) USING DELTA
COMMENT 'One row per workspace or dataflow override';
